SELECT oh.ORDER_NO as \"ORDER NUMBER\", oh.STATUS,  oh.SUPPLIER,  s.SUP_NAME as \"SUPPLIER NAME\", oh.LOCATION as \"LOCATION\",  oh.DEPT as \"DEPARTMENT\",  d.DEPT_NAME as \"DEPARTMENT NAME\",  COUNT(DISTINCT ol.ITEM) AS \"ITEM COUNT\", SUM(ol.QTY_ORDERED) AS \"TOTAL QUANTITY\", ROUND(SUM(ol.QTY_ORDERED)/NULLIF(SUM(isc.TI * isc.HI),0),2) AS  \"ESTIMATED PALLETS\" FROM MFCS_RDS.RDS_WV_ORDHEAD oh     JOIN MFCS_RDS.RDS_WV_ORDLOC ol ON oh.ORDER_NO = ol.ORDER_NO     JOIN MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY isc ON ol.ITEM = isc.ITEM AND oh.SUPPLIER = isc.SUPPLIER     JOIN MFCS_RDS.RDS_WV_SUPS s ON oh.SUPPLIER = s.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_DEPS d ON oh.DEPT = d.DEPT WHERE oh.STATUS IN ('A','W') GROUP BY oh.ORDER_NO, oh.STATUS, oh.SUPPLIER, s.SUP_NAME, oh.LOCATION, oh.DEPT, d.DEPT_NAME HAVING ROUND(SUM(ol.QTY_ORDERED)/NULLIF(SUM(isc.TI*isc.HI),0),2) &gt; 100 ORDER BY ROUND(SUM(ol.QTY_ORDERED)/NULLIF(SUM(isc.TI * isc.HI),0),2) DESC</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>ORDER NUMBER</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>STATUS</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>SUPPLIER NAME</ds:name><ds:datatype>varchar(240)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOCATION</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>DEPARTMENT</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>DEPARTMENT NAME</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>ITEM COUNT</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>TOTAL QUANTITY</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>ESTIMATED PALLETS</d